interface LockStrategy {
  run<T>(criticalSection: () => Promise<T>): Promise<T>;
}

const noLock: LockStrategy = { run: (cs) => cs() };

function serialized(): LockStrategy {
  let tail: Promise<unknown> = Promise.resolve();
  return { run: (cs) => (tail = tail.then(cs, cs)) };
}

